import json
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://127.0.0.1:8125"


def get_json(path):
    url = BASE + path
    try:
        with urllib.request.urlopen(url, timeout=30) as response:
            status = response.status
            body = response.read()
    except urllib.error.HTTPError as exc:
        raise RuntimeError(f"GET {url} failed with HTTP {exc.code}: {exc.read().decode('utf-8', 'replace')}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise RuntimeError(f"GET {url} request failed: {exc}") from exc
    if not 200 <= status < 300:
        raise RuntimeError(f"GET {url} failed with HTTP {status}")
    try:
        return json.loads(body)
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise RuntimeError(f"GET {url} returned invalid JSON: {exc}") from exc


try:
    last = get_json("/batches/last")
    last_seq = last["last_seq"]
    if not isinstance(last_seq, int) or isinstance(last_seq, bool):
        raise RuntimeError("GET /batches/last JSON field 'last_seq' is not an integer")

    result = get_json("/orders?after=" + urllib.parse.quote(str(last_seq), safe=""))
    orders = result["orders"] if isinstance(result, dict) and "orders" in result else result
    if not isinstance(orders, list):
        raise RuntimeError("GET /orders response does not contain an orders list")
    if not orders:
        sys.exit(0)

    seqs = []
    total_units = 0
    total_revenue_cents = 0
    revenue_by_region_cents = {}
    for index, order in enumerate(orders):
        if not isinstance(order, dict):
            raise RuntimeError(f"Order at index {index} is not an object")
        try:
            seq = order["seq"]
            units = order["units"]
            unit_price_cents = order["unit_price_cents"]
            region = order["region"]
        except KeyError as exc:
            raise RuntimeError(f"Order at index {index} is missing field {exc.args[0]!r}") from exc
        for name, value in (("seq", seq), ("units", units), ("unit_price_cents", unit_price_cents)):
            if not isinstance(value, int) or isinstance(value, bool):
                raise RuntimeError(f"Order at index {index} field {name!r} is not an integer")
        if not isinstance(region, str):
            raise RuntimeError(f"Order at index {index} field 'region' is not a string")
        revenue = units * unit_price_cents
        seqs.append(seq)
        total_units += units
        total_revenue_cents += revenue
        revenue_by_region_cents[region] = revenue_by_region_cents.get(region, 0) + revenue

    batch = {
        "batch_start_seq": min(seqs),
        "batch_end_seq": max(seqs),
        "order_count": len(orders),
        "total_units": total_units,
        "total_revenue_cents": total_revenue_cents,
        "revenue_by_region_cents": revenue_by_region_cents,
    }
    data = json.dumps(batch, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(
        BASE + "/batches",
        data=data,
        headers={"Content-Type": "application/json", "Content-Length": str(len(data))},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            status = response.status
            response.read()
    except urllib.error.HTTPError as exc:
        raise RuntimeError(f"POST {BASE}/batches failed with HTTP {exc.code}: {exc.read().decode('utf-8', 'replace')}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise RuntimeError(f"POST {BASE}/batches request failed: {exc}") from exc
    if not 200 <= status < 300:
        raise RuntimeError(f"POST {BASE}/batches failed with HTTP {status}")
except (KeyError, TypeError) as exc:
    print(f"Order batch processing failed: malformed JSON structure: {exc}", file=sys.stderr)
    sys.exit(1)
except RuntimeError as exc:
    print(f"Order batch processing failed: {exc}", file=sys.stderr)
    sys.exit(1)
